import {mkdir,readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {ProgramBuilder,audioTrack,audioFade,audioDuck,imagePut,instruction} from 'galbox-sdk/port-kit';
import {parseProgram,string} from 'galbox-sdk/protocol';
import {createReleaseManifest,inspectResource} from 'galbox-sdk/release';
const root='tests/player-app/public/media';await mkdir(root+'/assets',{recursive:true});const original=parseProgram(JSON.parse(await readFile('tests/fixtures/game-data/standard-novel/program.json','utf8'))),image=original.assets.find(a=>a.id==='shore');if(!image)throw new Error('image');const b=new ProgramBuilder({gameId:'lighthouse-media',title:'灯塔来信 · 风声回放',release:'media-1',entry:'main'}),background=b.asset('image',{...image,path:'../'+image.path});
async function audio(id:string,file:string,mime:'audio/ogg'|'audio/mpeg'|'audio/wav'){const bytes=await readFile('tests/fixtures/game-data/media-novel/assets/'+file);await writeFile(root+'/assets/'+file,bytes);return b.asset('audio',{id,path:'assets/'+file,mime,sha256:createHash('sha256').update(bytes).digest('hex')});}
const music=await audio('bgm-long','bgm-long.ogg','audio/ogg'),voice=await audio('voice-opus','voice-opus.ogg','audio/ogg'),short=await audio('voice-buffer','voice-buffer.wav','audio/wav'),signal=await audio('signal-mp3','signal-mp3.mp3','audio/mpeg');b.global({id:'route',kind:'string',initial:string('')});const page=(at:string,content:string)=>instruction('text.page',{at,textId:at.replace(':','.'),revision:'zh-1',speaker:'澪',content});
b.function({id:'main',entry:'wind:stage',layout:1,params:[],locals:[],returns:'void',code:[imagePut('wind:stage','background',background,{x:0,y:0,alpha:1}),audioFade('wind:silent','silent','bgm',0,1),instruction('task.join',{at:'wind:silent-wait',group:'silent',members:['silent']}),audioTrack('wind:music','music',music,{channel:'bgm',gain:.3,loop:true,loopStartMs:5000,loopEndMs:10000,restore:'replay'}),audioFade('wind:fade-in','fade-in','bgm',1,1000),audioDuck('wind:duck',true,.3,120,300),audioTrack('wind:voice','voice',voice,{channel:'voice',gain:.7,restore:'replay'}),page('wind:first','灯亮以前，听一听海风吧。信纸上留下的每一个字，都想再说给你听一次。'),audioTrack('wind:second-voice','voice',short,{channel:'voice',gain:.65,restore:'stop'}),page('wind:second','「还记得那封信吗？」澪问。我点点头，远处传来短短的一声回应。'),instruction('audio.policy',{at:'wind:policy',stopVoiceOnAdvance:false}),audioTrack('wind:signal','signal',signal,{channel:'sfx',gain:.4,restore:'replay'}),instruction('audio.wait',{at:'wind:signal-wait',task:'signal'}),page('wind:third','声音落下以后，海面恢复了安静。现在，该轮到我们回信了。'),audioFade('wind:fade-out','fade-out','bgm',0,1000),instruction('task.join',{at:'wind:fade-wait',group:'fade',members:['fade-out']}),instruction('audio.stop',{at:'wind:stop',channel:'bgm'}),instruction('choice',{at:'wind:choice',dest:'route',options:[{id:'send',text:'把回信送向海上',target:'wind:ending'},{id:'keep',text:'把回声留在灯下',target:'wind:ending'}]}),page('wind:ending','海风替我们收好最后一句话。灯亮着，回信就不会走失。'),instruction('profile.set',{at:'wind:unlock',key:'mediaComplete',value:{kind:'bool',value:true}}),instruction('control.end',{at:'wind:end'})]});
const program=b.build(),resources=await Promise.all(program.assets.map(async a=>inspectResource(a,new Uint8Array(await readFile(path.resolve(root,a.path))),bytes=>new TextDecoder('utf-8',{fatal:true}).decode(bytes))));const release=await createReleaseManifest({program,series:'1',resources},{async sha256(text){return createHash('sha256').update(text).digest('hex');}});for(const target of [root,'tests/fixtures/game-data/media-novel']){await mkdir(target,{recursive:true});await writeFile(`${target}/program.json`,JSON.stringify(program,null,2)+'\n');await writeFile(`${target}/program.json.release.json`,JSON.stringify(release,null,2)+'\n');}console.log('Built original wind chapter with 35s Vorbis, Opus/MP3, buffer voice, envelopes and natural waits');
